// Storage: a fenced cabinet with a top-slab shelf on the west wall, a flower pot on it. Lane: x=22 column and the
// z=22 row, from the ladder foot (25,18,22) to every piece. Lanterns stand on the floor (y=18) and on the desk.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  p: "potted_poppy",
  F: "spruce_fence",
  C: ["spruce_stairs", { facing: "north", half: "bottom" }],
  L: ["lantern", { hanging: "false" }],
  T: ["spruce_slab", { type: "top" }],
  P: "flower_pot",
};

// Origin [21,18,14]: x runs 21..25 (columns), z runs 14..22 (rows). Layer y=18 is the floor furniture; y=19 is the
// tops of the fences (desk, shelf); y=20 is what stands on those tops.
const ROWS = [
  [
    "p....", // z14: potted poppy in the north-west corner, under nothing
    "..F..", // z15: desk leg, under the dormer at x=23
    "..C..", // z16: chair facing north to the desk
    "....L", // z17: floor lantern on the east side
    "F....", // z18: cabinet fence
    "F....", // z19: cabinet fence
    "F....", // z20: cabinet fence
    ".....", // z21
    "L....", // z22: floor lantern in the south-west corner
  ],
  [
    ".....", // z14
    ".....", // z15
    ".....", // z16
    ".....", // z17
    "T....", // z18: cabinet shelf
    "T....", // z19: cabinet shelf
    "T....", // z20: cabinet shelf
    ".....", // z21
    ".....", // z22
  ],
];

export function build(g) {
  layers(g, [21, 18, 14], LEGEND, [ROWS[0]]);
  layers(g, [21, 19, 14], LEGEND, [ROWS[1]]);
  // desk top slab at (23,19,15), shelf slabs at x=21 z18..20
  g.set(23, 19, 15, ...[]);
}

